  "exports.eyebrow": "資料",
  "exports.title": "匯出與備份",
  "exports.subtitleStart": "下載一律限於",
  "exports.subtitleRest": "。每個檔案都會標示商家名稱和製作日期。",
  "exports.createBusinessFirst": "請先建立商家——匯出屬於商家，不屬於應用程式。",
  "exports.lockedTitle": "CSV 與 Excel 匯出是 Business 方案的功能",
  "exports.lockedDesc": "您的空間目前是 Essentials 方案。Business 方案新增 CSV 與 Excel 匯出、庫存估值、無限商品與員工、供應商、採購與組合包。",
  "exports.seeBusiness": "查看 Business 方案包含什麼",
  "exports.whatTheseAre": "這些檔案是什麼",
  "exports.about1": "每個資料集皆可下載為 CSV 或真正的 Excel 活頁簿（.xlsx）——完整的庫存活頁簿僅提供 Excel 版本，每個資料集各一張工作表。CSV 檔案可在 Excel、Numbers、Google Sheets 以及多數庫存應用程式中開啟。UTF-8 文字、引號內的逗號、備註中的換行，以及代碼開頭的零都會完整保留；以公式開頭的儲存格也會經過處理，讓試算表將其視為文字開啟。",
  "exports.about2": "在 Excel 檔案中，SKU、UPC、ISBN 與條碼皆為文字儲存格——絕不會變成科學記號，也不會去掉開頭的零——並套用欄寬、標題篩選，以及貨幣或數量格式。完整的庫存活頁簿會將商品、庫存數量、地點與異動分開放在不同工作表。",
  "exports.about3": "非常大的匯出每個資料集最多 20,000 列——達到上限時，檔案名稱會註明（truncated-20000），因此不完整的檔案絕不會被誤認為完整。",
  "exports.about4": "備份是您資料的快照，不是按一下就能還原。還原是需要手動、事先審查的工作，請妥善保管檔案——應用程式目前無法用它重建已刪除的商家。應用程式程式碼與 Base44 平台備份與這些檔案分開處理。",
  "exports.about5": "相片與附件僅列出其儲存連結——圖檔本身不會打包進下載檔案。",
  "exports.backupTitle": "完整備份",
  "exports.backupDesc": "一個檔案包含此商家的商品、地點、庫存數量、完整異動帳本、供應商、採購、訂單、退貨、盤點與上架清單——以及其設定檔。請存放在您能掌控的地方。",
