  "print.chooseStyleHint": "請先選擇樣式，再從清單中挑選商品。預覽畫面就是印出來的樣子。",
  "print.howToReach": "如何連接印表機",
  "print.howIntro": "此應用程式連接您已擁有的印表機——它本身不是印表機。共有四種連接方式，標籤在兩個方案中皆可透過任一方式列印。裝箱單、採購單、供應商文件與報表皆為 Business 方案專屬，不論連接方式為何。",
  "print.howBluetoothLead": "Bluetooth。",
  "print.howBluetoothBody": "在此頁面，於桌機版 Chrome 或 Edge 以及 Android 版 Chrome 上：選擇您的標籤印表機，標籤便直接傳送過去。iOS Safari 不支援——在 iPhone 上，Bluetooth 列印改由行動應用程式提供。僅支援 Zebra ZPL 或 Brother 專屬語言的印表機無法理解此頁面傳送的標籤；在稱為可用之前，會先以實體印表機核對。",
  "print.howWifiLead": "Wi-Fi。",
  "print.howWifiBody": "將印表機安裝到商店的 Wi-Fi 上，再使用「列印」按鈕——透過安裝在這台電腦上的印表機，經由商店網路列印。在 iPhone 上，AirPrint 已內建：同一 Wi-Fi 上的 AirPrint 印表機會直接出現在列印選單中，無需接線、無需額外應用程式，應用程式也不需要任何 AirPrint 專屬程式碼。印表機必須支援 AirPrint（多數新印表機皆支援），且手機與印表機必須在同一 Wi-Fi 上。",
  "print.howEthernetLead": "乙太網路。",
  "print.howEthernetBody": "以乙太網路線將印表機接到商店網路，安裝到電腦上，再透過「列印」按鈕列印。乙太網路是桌機與電腦的連接方式——iPhone 不使用乙太網路線。",
  "print.howUsbLead": "USB。",
  "print.howUsbBody": "以傳輸線將印表機接到電腦，再使用「列印」按鈕——透過安裝在該電腦上的印表機列印。在使用 USB OTG 傳輸線的 Android 手機上，上方的 USB 按鈕可直接與印表機通訊。iPhone 無法直接透過 USB 列印——沒有 WebUSB——因此請使用 Wi-Fi／AirPrint，或行動應用程式的 Bluetooth。",
  "print.howCordsLead": "接線仍可為 iPhone 服務，只是多了一個步驟。",
  "print.howCordsBody": "接到商店電腦的 USB 印表機，或接到網路的乙太網路印表機，會透過商店 Wi-Fi（AirPrint／共享印表機）在您的 iPhone 上出現——接線讓印表機穩固地連上網路，手機再無線連接它。",
  "print.howOfflineLead": "若網路中斷，",
  "print.howOfflineBody": "此頁面已有的標籤與文件仍可列印——「列印」按鈕、標籤 PDF、Bluetooth 與 USB 皆無需連線。需要連網的是最初載入頁面與其商品。完整離線模式（完全無連線時仍可在應用程式中工作）是另一個更大的開發項目，此處並未宣稱具備。",
