  "settings.cancelTerms.paymentBody": "付費試用方面，七天試用需要在註冊時提供付款方式。除非在適用的試用取消期限內取消，否則試用結束後將自動收取所選月費方案的費用。註冊時必須顯示價格、首次計費日期以及服務商特定的取消期限。試用計費透過 Stripe 進行。",
  "settings.cancelTerms.paymentTitle": "付款方式與自動續訂：",
  "settings.cancelTerms.remainingBody": "如果您已支付某個計費週期的費用，您可以保留使用權限至經驗證的付費到期日。提前終止需要服務商的適當確認以及任何適用的退款處理。免費試用的使用權限依服務商確認的試用終止日期結束。",
  "settings.cancelTerms.remainingTitle": "剩餘使用權限：",
  "settings.cancelTerms.storesBody": "如果您曾透過 Google Play 或 Apple App Store 訂閱，您的訂閱由該商店計費與管理。您可能需要在用來訂閱的同一個 Google 或 Apple 帳戶的訂閱項目中直接取消。取消另外的網站訂閱、解除安裝此應用程式，或請求刪除 Luminous StockHaven 帳戶，並不會自動取消由商店計費的訂閱。請查看您的購買收據以確認由誰向您收費。",
  "settings.cancelTerms.storesTitle": "Google Play 與 Apple App Store 訂閱（如果您曾透過商店訂閱）：",
  "settings.cancelTerms.title": "取消條款與條件",
  "settings.cancelTerms.trialBody": "七天試用每位符合資格的客戶僅可使用一次。取消試用或訂閱不會再獲得一次試用；回頭的客戶必須選擇付費訂閱。",
