  "staff.access.noSeatBody": "您的帳戶在此商家沒有員工席位，因此其庫存保持關閉。請請擁有者在「員工與角色」中新增您。",
  "staff.access.noSeatTitle": "此商家未對您的登入帳戶開放",
  "staff.access.pendingBody": "此商家有一封寄給您的電子郵件邀請尚未啟用。請請擁有者將您的員工狀態設為有效。在此之前，這裡不會顯示任何內容。",
  "staff.access.pendingTitle": "您的邀請尚未啟用",
  "staff.access.signOut": "登出",
  "staff.access.suspendedBody": "管理員已暫停此員工帳戶在目前商家的權限。請請他們將您恢復為有效狀態，然後重新登入。",
  "staff.access.suspendedTitle": "您的存取權限已暫停",
  "staff.addFirst": "新增第一位員工",
  "staff.addMember": "新增員工",
  "staff.emptyBody": "新增一位人員、指派角色與相應權限，他們就會收到電子郵件邀請，登入此商家。",
  "staff.emptyTitle": "尚無員工",
  "staff.eyebrow": "團隊",
  "staff.how.p1": "每位成員都有一個角色和自己的權限清單，因此您可以從角色出發，只更改其中一項，而不必建立新角色。編輯角色不會改寫已使用該角色的成員——請開啟成員以重新套用其角色預設值。",
  "staff.how.p2": "自訂角色是 Business 方案的功能：Essentials 方案使用五個內建角色（擁有者、經理、庫存店員、銷售店員、檢視者）。",
  "staff.how.p3": "邀請透過電子郵件寄送。成員只有在接受邀請後才能登入，將某人從此清單中移除並不會刪除其應用程式帳戶。",
  "staff.how.p4": "商店是指派給某人的地點。會記錄在他們的卡片上；他們能開啟哪些內容仍由其角色與權限決定。",
  "staff.how.p5": "權限決定每個人能開啟哪些內容：角色以外的選單項目會隱藏，而被封鎖的頁面會顯示「不在您的角色範圍內」的通知，而非頁面本身。變更會在該人員下次載入應用程式時生效；停用成員會將其完全鎖定在外。",
  "staff.how.p6": "管理員可以查看與變更所有資料、管理應用程式使用者與角色，且永不受員工角色限制。沒有員工記錄的人——例如新商家的擁有者——仍保有完整存取權限。",
  "staff.howTitle": "員工與角色的運作方式",
