  "auth.sameEmailNotice": "已經透過 Google Play 或 App Store 使用我們的應用程式了嗎？請在這裡使用同一個電子郵件 — 您登入應用程式時使用的那個 — 這樣您的商店和庫存就會跟著您。不同的電子郵件會開啟一個全新的、空的店面。",
