  "recovery.doneBody": "您的帳號電子郵件已變更，此登入現在又是您的一般登入了。歡迎回來。",
  "recovery.doneButton": "繼續前往我的商店",
  "settings.security.title": "安全性與備用金鑰",
  "settings.security.description": "請在需要之前先設定好您的備用金鑰：如果您哪天無法存取帳號電子郵件，它們就是您取回商店的方法。",
  "settings.security.genericError": "發生錯誤。請再試一次。",
