  "rewards.voided": "獎勵已作廢。",
  "workforce.tab.rewards": "獎勵",
  "training.lessons.mgr-give-rewards.step1": "開啟「人力管理」，點按「獎勵」。選擇團隊成員，然後選擇類型：店內折扣百分比、禮品卡，或用您自己的話描述的其他內容。",
  "training.lessons.mgr-give-rewards.step2": "為獎勵取一個簡短名稱，如願意可附上備註。對方會立即收到鈴鐺通知，獎勵會在其「我的獎勵」中等待，並有自己的代碼。",
  "training.lessons.mgr-give-rewards.step3": "依設計的界線：您只能獎勵員工。您不能獎勵自己或另一位經理 — 獎勵經理是擁有者的決定，應用程式會坦白拒絕。",
  "training.lessons.mgr-give-rewards.step4": "在收銀台，輸入團隊成員向您出示的代碼並標示為已使用 — 每個代碼只能使用一次。如果計劃變更，您可以作廢您給予的獎勵；擁有者的禮物由擁有者作廢。",
  "training.lessons.mgr-give-rewards.title": "給予您的員工獎勵",
  "training.lessons.owner-give-rewards.step1": "獎勵位於「人力管理」的「獎勵」分頁，且僅限 Business 方案 — 在 Essentials 方案下，該分頁會顯示一扇鎖上的門，讓您的團隊可以看到更大方案包含的內容。",
  "training.lessons.owner-give-rewards.step2": "您可以獎勵團隊中的任何人 — 員工和經理皆可。選擇人員，然後選擇類型：店內折扣百分比（任何您選擇的百分比）、可在任何地方使用的禮品卡，或任何您用自己的話描述的激勵。",
  "training.lessons.owner-give-rewards.step3": "獎勵會附帶自己的一次性代碼送達，並通知對方的鈴鐺。他們在收銀台出示代碼；擁有者或經理輸入代碼以標示為已使用。",
  "training.lessons.owner-give-rewards.step4": "列印或分享的獎勵憑條只會顯示您的商家名稱 — 絕不會顯示應用程式的名稱。這是您商店的感謝，不是廣告。",
  "training.lessons.owner-give-rewards.title": "給予獎勵（Business 方案）",
  "training.lessons.owner-rewards-oversight.step1": "您的經理也可以給予獎勵 — 僅限員工。應用程式會拒絕經理獎勵自己或另一位經理；獎勵經理永遠是您的決定。",
  "training.lessons.owner-rewards-oversight.step2": "您可以在「獎勵歷史」中查看商家中的每一個獎勵：誰給的、誰收到的，以及它是可以使用、已使用還是已作廢。經理只能看到他們給予的獎勵和他們收到的獎勵。",
  "training.lessons.owner-rewards-oversight.step3": "您可以作廢任何獎勵，包括您的經理給予的獎勵。經理可以作廢他們自己的禮物，但絕不能作廢您的。",
  "training.lessons.owner-rewards-oversight.step4": "每個代碼只能使用一次，作廢的獎勵永遠無法使用 — 歷史始終顯示獎勵的最終結果。",
  "training.lessons.owner-rewards-oversight.title": "監督獎勵：您經理的給予情況",
  "training.lessons.staff-your-rewards.step1": "當您的經理或擁有者給予您獎勵時，您的鈴鐺會響起。開啟「人力管理」，點按「獎勵」，在「我的獎勵」下查看。",
  "training.lessons.staff-your-rewards.step2": "每個獎勵都有自己的代碼。請妥善保管 — 在收銀台出示代碼的人就是使用該獎勵的人。",
  "training.lessons.staff-your-rewards.step3": "若要使用，請在購買時出示代碼。收銀台的人員會輸入代碼並標示為已使用 — 每個代碼只能使用一次。",
  "training.lessons.staff-your-rewards.step4": "獎勵是 Business 方案的福利。如果您的商店未使用 Business 方案，「獎勵」分頁會改為顯示一扇鎖上的門 — 那是方案的安排，不是錯誤。",
  "training.lessons.staff-your-rewards.title": "您的獎勵：找到您的代碼並使用它",
  "training.module.rewards": "獎勵與激勵",
