  "support.contextNote": "為了讓我們找到問題，您的備註會自動包含您所在的頁面、您的商家和角色（如已選擇）、您的方案、您的應用程式語言，以及您使用的手機或瀏覽器類型。它絕不會包含您的商品、庫存或銷售。",
  "support.description": "有東西壞了、有東西看起來不對，或有想法要分享嗎？請在這裡告訴我們 — 您的備註會直接送交應用程式背後的團隊。",
